mapper.select:
SELECT t.id AS id, t.name AS name, COALESCE(SUM(sp.view_count), 0) AS viewCount, COALESCE(SUM(sp.sales_revenue), 0) AS salesRevenue, COALESCE(SUM(sp.refund), 0) AS refund, COALESCE(SUM(sp.net_sales), 0) AS netSales, COALESCE(SUM(sp.investment), 0) AS investment FROM team t LEFT JOIN session_performance sp ON sp.team_id = t.id AND sp.tenant_id = #{req.tenantId} AND sp.stats_date BETWEEN #{req.startDate} AND #{req.endDate} AND sp.is_deleted = 0 WHERE t.tenant_id = #{req.tenantId} AND t.is_deleted = 0
AND t.company_id = #{req.companyId}
AND t.dept_id = #{req.deptId}
AND t.id IN
#{id}
AND t.name LIKE CONCAT('%', #{req.name}, '%')
GROUP BY t.id ORDER BY
viewCount salesRevenue refund netSales investment salesRevenue
ASC DESC
